css:
/* 横割り + カードを跨がせる */
section{background:linear-gradient(#fce8ef 0 62%, #ea4b93 62% 100%)}
.card{position:relative; z-index:1; background:#fff; border-radius:40px;
  margin:60px 90px -70px}          /* 下マージン負値で下段へ沈める */

/* 縦割り（明度差だけ）+ 見出しを食い込ませる */
section{background:linear-gradient(90deg,#161719 0 27%, #0a0b0d 27% 100%)}
h2{position:relative; z-index:1; margin-left:6%}

/* コンテンツを避けない色帯 */
.sec{position:relative; isolation:isolate}
.sec::after{content:''; position:absolute; inset:auto 0 0 0; height:19%;
  background:#f3f3e6; z-index:-1}
